   var q=new Queue<string>();q.Enqueue(w.CurrentTravelDestinationId);var seen=new HashSet<string>{w.CurrentTravelDestinationId};var parent=new Dictionary<string,string>();while(q.Count>0){string id=q.Dequeue();if(id==destination)break;foreach(var r in w.Campaign!.Connections.Where(r=>r.FromAreaId==id&&r.RequiredFlag==""))if(seen.Add(r.ToAreaId)){parent[r.ToAreaId]=id;q.Enqueue(r.ToAreaId);}}
   var route=new List<string>();for(string id=destination;id!=w.CurrentTravelDestinationId;id=parent[id])route.Add(id);route.Reverse();foreach(var next in route){Settle(w);foreach(var f in w.Features.Where(f=>f.Kind=="door"))f.Used=true;var link=w.Campaign!.Connections.Single(r=>r.FromAreaId==w.CurrentTravelDestinationId&&r.ToAreaId==next);var exit=w.Features.Single(f=>f.Id==link.ExitFeatureId);var cells=w.Floors.Where(p=>p.Distance(exit.Pos)<=2&&w.CanStand(p.Center,null,false)).OrderBy(p=>p.Distance(exit.Pos)).ToArray();int slot=0;foreach(var p in w.Party)p.Pos=cells[slot++];w.Reveal();check(w.TravelCampaignTo(next),"Phase 30 real provenance route travels to "+next);}
  }
