  world=Fixture(5);Clear(world);var shotgun=Take(world,5,0);check(shotgun.Broken&&!Do(world,"ext30-repair"),"Phase 30 garage shotgun starts broken and refuses repair without supplies");Take(world,5,1);Add(world,world.Campaign!.Infrastructure!.GeneratorCost[0].ItemId);check(Do(world,"ext30-repair")&&!shotgun.Broken&&shotgun.LoadedAmmunition==null&&world.PartyLeader.Inventory.Count(world.Campaign.Infrastructure.GeneratorCost[0].ItemId)==0,"Phase 30 shotgun repair consumes real material without inventing ammunition");world.Save(path);World.Load(path);
  world=Fixture(10);Clear(world);check(Do(world,"ext30-freezer"),"Phase 30 taco freezer opens and creates a saved delayed event");state=world.LowerMallProgress(310)!;double deadline=state.ExteriorTimers["freezerAt"];world.Save(path);world=World.Load(path);check(world.LowerMallProgress(310)!.ExteriorTimers["freezerAt"]==deadline&&Do(world,"ext30-close"),"Phase 30 closing the freezer cancels its saved mist deadline");world.AdvanceCampaignSeconds(400);check(!world.Actors.Any(a=>a.Name=="The Hungry One"),"Phase 30 safely closed freezer does not create a delayed horror");
  world=Fixture(3);Clear(world);var drink=Take(world,3,0);int speed=world.PartyLeader.EffectiveSpeedFeet,exhaustion=world.PartyLeader.Needs.Exhaustion;check(world.UseLowerMallItem(world.PartyLeader,drink.InstanceId)&&world.PartyLeader.EffectiveSpeedFeet==speed+5,"Phase 30 employee energy drink gives its real five-foot speed benefit");world.Save(path);world=World.Load(path);world.AdvanceCampaignSeconds(3600);check(world.PartyLeader.Needs.Exhaustion==exhaustion+1&&!world.PartyLeader.Character.HasCondition("ext30-energy"),"Phase 30 energy speed expires with exactly one fatigue cost after reload");
  world=Fixture(7);Clear(world);var lamp=Take(world,7,1);check(lamp.Charges==0&&!Do(world,"ext30-repair"),"Phase 30 broken alley flashlight cannot be used or repaired without a Smart survivor or material");check(world.ChooseSurvivorClass(world.PartyLeader,"smart"),"Phase 30 flashlight fixture selects Smart through actual survivor progression");check(Do(world,"ext30-repair")&&lamp.Charges==1&&world.UseEquipment(world.PartyLeader,lamp.InstanceId)&&lamp.Charges==0&&world.EquipmentEffects.Any(e=>e.Kind=="light"),"Phase 30 actual flashlight repair restores a finite working light without pretending a supply item has weapon wear");world.Save(path);check(World.Load(path).EquipmentEffects.Any(e=>e.Kind=="light"),"Phase 30 repaired flashlight illumination persists through reload");
